sys_variable_value.value:
(function execute(inputs, outputs) {

    gs.info('DEBUG - ScheduleSysId recebido: ' + inputs.scheduleSysId);

    var enrollments = [];
    var gr = new GlideRecord('x_1805892_compan_0_enrollment');
    gr.addQuery('schedule', inputs.scheduleSysId);
    gr.addQuery('state', 3);
    gr.query();

    while (gr.next()) {
        enrollments.push(gr.requested_for.name.toString());
    }

    if (enrollments.length === 0) {
        outputs.participant_list = "No enrolled participants found.";
    } else {
        outputs.participant_list = enrollments.join(', ');
    }

})(inputs, outputs);

